#!/bin/bash\n\n# Update all admin routes to use D1 auth\n\nADMIN_ROUTES=$(find src/app/api/admin -name \"route.ts\" -exec grep -l \"requireAdmin\" {} \\;)\n\nfor file in $ADMIN_ROUTES; do\n  echo \"Updating $file\"\n  \n  # Check if file already has getAuthDb import\n  if ! grep -q \"import.*getAuthDb\" \"$file\"; then\n    # Add import after other imports\n    if grep -q \"from.*next/server\" \"$file\"; then\n      sed -i \"/from.*next\\/server/a import { getAuthDb } from \\\"@\\/lib\\/auth-d1\\\";\" \"$file\"\n    fi\n  fi\n  \n  # Update requireAdmin calls to pass db parameter\n  sed -i 's/await requireAdmin(request)/await requireAdmin(request, getAuthDb())/g' \"$file\"\n  sed -i 's/await requireAdmin(req)/await requireAdmin(req, getAuthDb())/g' \"$file\"\n  \ndone\n\necho \"Updated $(echo $ADMIN_ROUTES | wc -w) admin route files\"\n